require __DIR__.'/app/bootstrap.php';$u=require_login();$auction=store_auction((int)($_GET['id']??$_POST['id']??0));if(!$auction||$auction['status']!=='ended'||(int)$auction['winner_user_id']!==(int)$u['id']){http_response_code(403);exit('Winner checkout unavailable.');}$err=null;if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$method=(string)($_POST['payment_method']??'advance');$order=store_create_order((int)$u['id'],$method,['name'=>$_POST['name']??$u['name'],'phone'=>$_POST['phone']??$u['phone'],'email'=>$_POST['email']??$u['email'],'address'=>$_POST['address']??'','city'=>$_POST['city']??'','notes'=>'Auction winner checkout'],(int)$auction['id']);header('Location: '.($method==='advance'?'/shop-payment.php?order='.$order:'/order.php?id='.$order));exit;}catch(Throwable $e){$err=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auction Winner Checkout</title><link rel="stylesheet" href="/assets/themes/landing/base.css?v=240"><link rel="stylesheet" href="/assets/live-commerce-3.4.0.css?v=340"></head><body class="lc-page"><section class="shop-section"><div class="lt-shell" style="max-width:750px"><form method="post" class="shop-panel"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($auction['id'])?>"><h2>Auction Winner Checkout</h2><p><b><?=e($auction['title'])?></b><br>Winning bid: Rs <?=e(number_format((float)$auction['current_price'],0))?></p><?php if($err):?><div style="color:#b91c1c"><?=e($err)?></div><?php endif;?><label>Name</label><input name="name" value="<?=e($u['name'])?>"><label>Phone</label><input name="phone" value="<?=e($u['phone'])?>" required><label>Address</label><textarea name="address"></textarea><label>City</label><input name="city" value="<?=e(setting('default_city','Shahkot'))?>"><label>Payment</label><select name="payment_method"><?php if($auction['product_type']!=='digital'&&(int)$auction['allow_cod']===1&&setting_bool('store_cod_enabled',true)):?><option value="cod">Cash on Delivery</option><?php endif;?><?php if((int)$auction['allow_advance']===1&&setting_bool('store_advance_enabled',true)):?><option value="advance">Advance Payment</option><?php endif;?></select><button class="cv-primary-btn" style="border:0;margin-top:12px">Create Winning Order</button></form></div></section></body></html>
